const handleProfileAction = async (action: "follow" | "hire" | "like") => {
  // Optimistic UI
  if (action === "follow") {
    setIsFollowing(!isFollowing);
    setFollowersCount((prev) => isFollowing ? Math.max(0, prev - 1) : prev + 1);
  } else if (action === "hire") {
    setHasHired(!hasHired);
    message.success(!hasHired ? "ส่งคำขอจ้างงานแล้ว" : "ยกเลิกคำขอจ้างงานแล้ว");
  } else if (action === "like") {
    setIsLiked(!isLiked);
  }

  try {
    const res = await fetch(`/api/profile/${id}/action`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action }),
    });

    if (!res.ok) {
      // Revert if failed
      if (action === "follow") {
        setIsFollowing(isFollowing);
        setFollowersCount((prev) => isFollowing ? prev + 1 : Math.max(0, prev - 1));
      } else if (action === "hire") {
        setHasHired(hasHired);
      } else if (action === "like") {
        setIsLiked(isLiked);
      }
      message.error("ดำเนินการไม่สำเร็จ");
    }
  } catch (error) {
    console.error("Profile Action error:", error);
    message.error("เกิดข้อผิดพลาดในการดำเนินการ");
  }
};

